'use client';
import {useState,useEffect,useRef, type ReactNode} from 'react';
import {Leaf,Heart,Clock,Users,Search,Check,X,Menu,SlidersHorizontal,Camera,Trash2,Download,Printer,Sun,Sprout,Snowflake,Flower2,Bookmark,Plus,ChevronDown,ChevronLeft,ChevronRight,Cloud,CheckCircle2,LogOut,Play,Volume2,Square,Maximize2,Type,Shuffle,MessageCircle} from 'lucide-react';
import catalogue from '../content/activities.json';
import privacy from '../content/privacy.json';
import videoData from '../content/videos.json';
import CommunityGallery from './community-gallery';
import SeasonFriend from './season-friend';
import FeedbackForm from './feedback-form';
import HeroCover from './hero-cover';
import ButterflyAccents from './butterfly-accents';
import {activityImageUrl} from '../lib/activity-image';
import EmailAccount from './email-account';
